# Now let's check comments on each task to see if someone agreed to take it
for task in all_tasks:
    task_id = task['task_id']
    comments = apis.todoist.show_task_comments(task_id=task_id, access_token=access_token)
    print(f"\nTask {task_id} ({task['title']}):")
    if isinstance(comments, list):
        for c in comments:
            print(f"  Comment by {c.get('user_name', c.get('user', 'unknown'))}: {c['content']}")
    else:
        print(f"  Response: {comments}")

